//
// ADR-001: Sessions expire when 30 minutes have elapsed since `lastActivityAt`.
// The boundary at exactly 30 minutes counts as expired.

export interface Session {
  lastActivityAt: number; // epoch milliseconds
}

const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes

/**
 * Returns true when the session has expired per ADR-001: sessions expire
 * once 30 minutes have elapsed since `lastActivityAt`. Exactly 30 minutes
 * elapsed counts as expired.
 */
export function isSessionExpired(session: Session, now: number): boolean {
  const elapsed = now - session.lastActivityAt;
  return elapsed >= SESSION_TIMEOUT_MS;
}

/**
 * Returns the number of milliseconds remaining until the existing 30-minute
 * session timeout (see ADR-001), clamped to zero. If the session has already
 * expired (elapsed >= 30 minutes), returns 0.
 */
export function remainingSessionMs(session: Session, now: number): number {
  const elapsed = now - session.lastActivityAt;
  const remaining = SESSION_TIMEOUT_MS - elapsed;
  return remaining > 0 ? remaining : 0;
}

